import{_ as a,o as l,c as n,a2 as o}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"内部机制：内核日志（klog）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/klog.md","filePath":"zh/internals/klog.md"}'),s={name:"zh/internals/klog.md"};function t(i,e,c,r,d,p){return l(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="内部机制-内核日志-klog" tabindex="-1">内部机制：内核日志（klog） <a class="header-anchor" href="#内部机制-内核日志-klog" aria-label="Permalink to &quot;内部机制：内核日志（klog）&quot;">​</a></h1><p><code>kernel/lib/lib_klog.{c,h}</code> - 29 个声明；编号的第 6 个：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>klog_write(level, fmt, ...)      /* the entry point */</span></span>
<span class="line"><span>klog_set_level(lvl)</span></span>
<span class="line"><span>klog_set_level_enabled(lvl, on)</span></span>
<span class="line"><span>klog_flush()</span></span>
<span class="line"><span>klog_rotate()</span></span>
<span class="line"><span>klog_filter_set(min_level)</span></span></code></pre></div><h2 id="行为-已通过端到端验证-非目标性描述" tabindex="-1">行为（已通过端到端验证，非目标性描述） <a class="header-anchor" href="#行为-已通过端到端验证-非目标性描述" aria-label="Permalink to &quot;行为（已通过端到端验证，非目标性描述）&quot;">​</a></h2><ul><li>级别 DEBUG/INFO/WARN/ERROR/FATAL；支持按级别启用 + 全局最低过滤器。</li><li>环形缓冲区镜像到串口；持久化文件（/etc 上的 <code>kernel.log</code>）按需刷新。</li><li>在 4096 字节阈值处轮转：<code>kernel.log</code> 变为 <code>kernel.log.1</code>（真正的代际对 - S5 断言两个大小）。</li><li>过滤器证明：级别 &gt;= 3 仅允许 ERR/FATAL，而 dbg/inf/wrn 计数归零（S6 的确切断言）。</li></ul><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h2><p><code>dmesg</code>（环形缓冲区）、<code>logcat</code>（实时跟踪）、<code>logctl</code>（级别/过滤器）、<code>crashlog</code>（崩溃记录）。</p><h2 id="什么写入" tabindex="-1">什么写入 <a class="header-anchor" href="#什么写入" aria-label="Permalink to &quot;什么写入&quot;">​</a></h2><p>所有子系统的错误路径 + 健康警报 + 看门狗策略终止 - 日志即是系统叙述；<code>logctl</code> 是你降低噪音而不丢失错误的方式。</p>`,9)])])}const _=a(s,[["render",t]]);export{g as __pageData,_ as default};
